// Exact degree-one cohomology jump ideals, distinct from the Fitting ideals
// of the universal homology module. Cached decompositions are generated by
// compute-jump-cache.mjs and include scheme/radical equality certificates.
import {maskIndices} from './math.js';
import {JUMP_IDEAL_CACHE} from './jump-cache.js';
import {computeLiveResonance} from './resonance-live.js';

export const jumpGeometryKey=data=>JSON.stringify(data.lines.map(l=>l.map(String)));
const normalizeKind=kind=>kind==='local'||kind==='characteristic'?'local':kind==='aomoto'||kind==='resonance'?'aomoto':(()=>{throw Error('local または aomoto を指定してください');})();
const indexCheck=(data,k)=>{k=Number(k);if(!Number.isInteger(k)||k<1||k>data.n+1)throw Error('深さ k は 1 から n+1 の整数にしてください');return k;};
const variables=(n,kind)=>Array.from({length:n},(_,i)=>(kind==='local'?'t':'a')+(i+1));
const monomialString=(powers,vars)=>powers.flatMap((e,i)=>e?[vars[i]+(e===1?'':'^'+e)]:[]).join('*')||'1';

export function polynomialChamberMatrix(data,kind='local'){
  kind=normalizeKind(kind);const vars=variables(data.n,kind);
  return data.d1.map(row=>{
    // Multiplication by this row monomial is a unit over the Laurent ring.
    const clear=kind==='local'?row.reduce((s,e)=>e.deg?s|e.minus:s,0):0;
    return row.map(e=>{
      if(!e.deg)return '0';
      if(kind==='aomoto')return '('+e.deg+')*('+maskIndices(e.sep,data.n).map(i=>vars[i]).join('+')+')';
      const a=vars.map((_,i)=>((clear>>i)&1)+((e.plus>>i)&1)),b=vars.map((_,i)=>((clear>>i)&1)-((e.minus>>i)&1));
      return '('+e.deg+')*('+monomialString(a,vars)+'-'+monomialString(b,vars)+')';
    });
  });
}

export function singularJumpScript(data,kind='local',k=1){
  kind=normalizeKind(kind);k=indexCheck(data,k);if(!data.n)throw Error('空配置には深さ 1 の jump locus はありません');
  const n=data.n,r=n-k+1,vars=variables(n,kind),D=polynomialChamberMatrix(data,kind),compact=kind==='local'&&k===1&&n>=2;
  const minor=d=>d<=0?'ideal(1)':d>Math.min(data.b2,n-1)?'ideal(0)':'minor(D,'+d+')';
  return `// Chamber Lab: exact cohomology jump ideal J^1_${k}.
// J=I_${r}(d0 direct-sum d1)=Fitt_${k}(coker transpose(d0 direct-sum d1)).
// It is not asserted to be Fitt_${k-1} of universal H1.
// Geometry: ${jumpGeometryKey(data)}
// Flag used for this reproducible computation: ${JSON.stringify(data.flag.map(String))}
// d0 has one column. Its entries generate the augmentation ideal Aug.
// Thus J=I_r(d1)+Aug*I_(r-1)(d1). All n-minors of d1 vanish since d1*d0=0.
LIB "primdec.lib";
ring R=0,(${vars.join(',')}),dp;
short=0;
option(redSB);
option(noredefine);
matrix D[${Math.max(1,data.b2)}][${n}]=${D.length?D.flat().join(','):'0'};
matrix firstBoundary[${n}][1]=${data.d0.map(([e])=>kind==='local'?'('+maskIndices(e.plus,n).map(i=>vars[i]).join('*')+'-1)':'('+maskIndices(e.sep,n).map(i=>vars[i]).join('+')+')').join(',')};
if(size(ideal(D*firstBoundary))!=0){print("@@INVALID complex identity");exit;}
ideal Aug=${vars.map(t=>kind==='local'?t+'-1':t).join(',')};
${k===1&&n>=2?`// The maximal minors in columns omitting j equal d0_j times the same
// signed quotient. Since gcd(d0_j)=1, the quotient is polynomial.
// Therefore I_(n-1)(D)=Aug*C and J^1_1=Aug^2*C; avoid n-fold duplicate minors.
matrix E[${Math.max(1,data.b2)}][${n-1}];
for(int er=1;er<=${data.b2};er++){for(int ec=1;ec<=${n-1};ec++){E[er,ec]=D[er,ec+1];}}
ideal C=${data.b2>=n-1?'minor(E,'+(n-1)+')':'ideal(0)'};
for(int ci=1;ci<=size(C);ci++){
  poly quotientPolynomial=C[ci]/(${vars[data.cuts[0].i]}${kind==='local'?'-1':''});
  if(C[ci]-quotientPolynomial*(${vars[data.cuts[0].i]}${kind==='local'?'-1':''})!=0){print("@@INVALID nonexact maximal-minor quotient");exit;}
  C[ci]=quotientPolynomial;
  ${kind==='local'?`// Remove each minor's monomial unit before Groebner reduction.
  poly remainingTerms=C[ci];
  if(remainingTerms!=0){
    intvec minimumExponent=leadexp(remainingTerms);
    while(remainingTerms!=0){
      intvec currentExponent=leadexp(remainingTerms);
      for(int ei=1;ei<=nvars(basering);ei++){if(currentExponent[ei]<minimumExponent[ei]){minimumExponent[ei]=currentExponent[ei];}}
      remainingTerms=remainingTerms-lead(remainingTerms);
    }
    poly monomialUnit=1;
    for(int ei=1;ei<=nvars(basering);ei++){monomialUnit=monomialUnit*var(ei)^minimumExponent[ei];}
    C[ci]=C[ci]/monomialUnit;
  }`:''}
}
C=std(C);
${compact?'// Keep J=Aug^2*C as an exact product, avoiding its redundant expanded Groebner basis.':'ideal J=Aug^2*C;'}`:`ideal Smaller=std(${minor(r-1)});
ideal Larger=std(${minor(r)});
ideal J=Larger+Aug*Smaller;`}
int rawCount=size(${compact?'C':'J'});
${compact?'C':'J'}=std(${compact?'C':'J'});
${kind==='local'?`// Clear the polynomial coordinate-boundary artifacts: contract the Laurent ideal.
// sat() returns an ideal in Singular 4.4.1, a list in older releases.
def saturationResult=sat(${compact?'C':'J'},ideal(${vars.join('*')}));
if(typeof(saturationResult)=="list"){${compact?'C':'J'}=saturationResult[1];}else{${compact?'C':'J'}=saturationResult;}
${compact?'C':'J'}=std(${compact?'C':'J'});`:''}
proc emitIdeal(ideal I,string label){
  print("@@IDEAL "+label+" "+string(size(I)));
  for(int z=1;z<=size(I);z++){print(string(I[z]));}
}
print("@@RAW "+string(rawCount));
${compact?'print("@@FACTORED 2");emitIdeal(Aug,"augmentation");emitIdeal(C,"quotient");':'emitIdeal(J,"scheme");'}
list P;
if(size(${compact?'C':'J'})==1 && ${compact?'C':'J'}[1]==1){P=list();}else{P=minAssGTZ(${compact?'C':'J'});}
${compact?`// sqrt(Aug^2*C)=Aug intersect sqrt(C). Add the identity only if needed.
ideal augmentationBasis=std(Aug);
int pointNeeded=1;
for(int pidx=1;pidx<=size(P);pidx++){if(size(reduce(P[pidx],augmentationBasis))==0){pointNeeded=0;}}
if(pointNeeded){P[size(P)+1]=augmentationBasis;}`:''}
print("@@PRIMES "+string(size(P)));
ideal H=1;
int irredundant=1;
for(int i=1;i<=size(P);i++){
  ideal Pi=std(P[i]);P[i]=Pi;
  emitIdeal(Pi,"prime"+string(i));
  print("@@DIM "+string(dim(Pi)));
  int isLinearForm=1;int isBinomialForm=1;
  for(int g=1;g<=size(Pi);g++){
    if(deg(Pi[g])>1){isLinearForm=0;}
    if(size(Pi[g])!=2){isBinomialForm=0;}
  }
  print("@@FORM "+string(isLinearForm)+" "+string(isBinomialForm));
  if(isBinomialForm){
    for(int g=1;g<=size(Pi);g++){
      intvec e=leadexp(Pi[g]);intvec f=leadexp(Pi[g]-lead(Pi[g]));
      print("@@LATTICE "+string(e-f));
    }
  }
  H=intersect(H,Pi);
}
H=std(H);
emitIdeal(H,"radical");
// Equality of radicals is verified without trusting a list of candidates:
// J subset H; every generator h of H has a power h^e in J;
// H is an intersection of the displayed absolutely prime ideals.
${compact?`int included=1;
for(int pidx=1;pidx<=size(P);pidx++){
  if(size(reduce(C,P[pidx]))!=0 && size(reduce(Aug,P[pidx]))!=0){included=0;}
}`:'int included=size(reduce(J,H))==0;'}
int nilpotent=1;
for(int j=1;j<=size(H);j++){
  poly h=reduce(H[j],${compact?'C':'J'});int exponent=1;
  while(h!=0 && exponent<64){h=reduce(h*h,${compact?'C':'J'});exponent=exponent*2;}
  ${compact?'if(reduce(H[j],augmentationBasis)!=0){nilpotent=0;}':''}
  if(h!=0){nilpotent=0;}
  print("@@POWER "+string(${compact?'exponent+2':'exponent'})+" "+string(h==0));
}
for(int i=1;i<=size(P);i++){
  for(int j=1;j<=size(P);j++){
    if(i!=j && size(reduce(P[i],P[j]))==0){irredundant=0;}
  }
}
print("@@CHECK "+string(included)+" "+string(nilpotent)+" "+string(irredundant));
print("@@DONE");
exit;
`;
}

function definition(data,kind,k){const r=data.n-k+1;return {degree:1,depth:k,minorSize:r,middleRank:data.n,blockColumns:data.n+1,
  equation:'J¹_'+k+' = I_'+r+'(d⁰ ⊕ d¹) = I_'+r+'(d¹) + Aug · I_'+(r-1)+'(d¹)',
  fitting:'Fitt_'+k+'(coker((d⁰ ⊕ d¹)ᵀ))',
  schemeWarning:'The jump ideal retains its scheme structure. The irreducible components below describe its radical, not a primary decomposition.',
  saturation:kind==='local'?'Contracted from Q[t₁±¹,…,tₙ±¹] by saturation with (t₁⋯tₙ)^∞; coordinate hyperplanes are excluded.':'No Laurent saturation for the resonance ideal.'};}

class Bound extends Error{}
const zero=()=>new Map(),one=n=>new Map([[Array(n).fill(0).join(','),1n]]);
const gcd=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b){const c=a%b;a=b;b=c;}return a;};
function sparseEngine(data,kind,options){
  const n=data.n,start=Date.now(),ctx={operations:0,minors:0,maxOperations:options.maxOperations??1500000,maxTerms:options.maxTerms??10000,maxMinors:options.maxMinors??500,maxTimeMs:options.maxTimeMs??2500};
  const guard=p=>{if(p&&p.size>ctx.maxTerms)throw new Bound('多項式の項数上限');if(++ctx.operations%256===0&&(ctx.operations>ctx.maxOperations||Date.now()-start>ctx.maxTimeMs))throw new Bound('正確計算の処理上限');};
  const add=(a,b,sign=1n)=>{const c=new Map(a);for(const [m,x]of b){const v=(c.get(m)||0n)+sign*x;if(v)c.set(m,v);else c.delete(m);guard(c);}return c;};
  const mul=(a,b)=>{const c=zero();for(const [ma,x]of a){const ea=ma.split(',').map(Number);for(const [mb,y]of b){const eb=mb.split(',').map(Number),key=ea.map((v,i)=>v+eb[i]).join(','),v=(c.get(key)||0n)+x*y;if(v)c.set(key,v);else c.delete(key);guard(c);}}return c;};
  const term=(e,c=1n)=>c?new Map([[e.join(','),c]]):zero();
  const augmented=Array.from({length:n},(_,i)=>{const e=Array(n).fill(0);e[i]=1;return kind==='local'?add(term(e),one(n),-1n):term(e);});
  const matrix=data.d1.map(row=>{const clear=kind==='local'?row.reduce((s,e)=>e.deg?s|e.minus:s,0):0;return row.map(e=>{
    if(!e.deg)return zero();if(kind==='aomoto'){let p=zero();for(const i of maskIndices(e.sep,n)){const ex=Array(n).fill(0);ex[i]=1;p=add(p,term(ex,BigInt(e.deg)));}return p;}
    const a=Array.from({length:n},(_,i)=>((clear>>i)&1)+((e.plus>>i)&1)),b=Array.from({length:n},(_,i)=>((clear>>i)&1)-((e.minus>>i)&1));return add(term(a,BigInt(e.deg)),term(b,BigInt(e.deg)),-1n);
  });});
  const normalize=p=>{if(!p.size)return p;let content=0n;const powers=Array(n).fill(Infinity);for(const [m,c]of p){content=gcd(content,c);m.split(',').forEach((v,i)=>powers[i]=Math.min(powers[i],Number(v)));}const keys=[...p.keys()].sort(),sign=p.get(keys[0])<0n?-1n:1n;
    return new Map([...p].map(([m,c])=>[m.split(',').map((v,i)=>Number(v)-(kind==='local'?powers[i]:0)).join(','),c/(content*sign)]));};
  const key=p=>[...p].sort((a,b)=>a[0].localeCompare(b[0])).map(([m,c])=>m+':'+c).join(';');
  const determinant=(rows,cols)=>{const d=rows.length,memo=new Map();function calc(mask){if(mask===0)return one(n);if(memo.has(mask))return memo.get(mask);const bits=Array.from({length:d},(_,i)=>i).filter(i=>mask&(1<<i)),r=d-bits.length;let p=zero();bits.forEach((j,s)=>{if(matrix[rows[r]][cols[j]].size)p=add(p,mul(matrix[rows[r]][cols[j]],calc(mask^(1<<j))),s%2?-1n:1n);});memo.set(mask,p);return p;}return calc((1<<d)-1);};
  function* choices(m,d,start=0,prefix=[]){if(!d){yield prefix;return;}for(let i=start;i<=m-d;i++)yield*choices(m,d-1,i+1,[...prefix,i]);}
  function* minors(d){if(d<=0){yield one(n);return;}if(d>Math.min(data.b2,n-1))return;if(d>(options.maxMinorOrder??8))throw new Bound('小行列式の次数上限');
    for(const rows of choices(data.b2,d))for(const cols of choices(n,d)){if(ctx.minors>=ctx.maxMinors)throw new Bound('小行列式の個数上限');ctx.minors++;yield normalize(determinant(rows,cols));}}
  const generators=new Map();const insert=p=>{p=normalize(p);if(p.size)generators.set(key(p),p);};
  let complete=true,reason=null;
  return {compute(r){try{for(const p of minors(r))insert(p);for(const p of minors(r-1))if(p.size)for(const a of augmented)insert(mul(a,p));}catch(e){if(!(e instanceof Bound))throw e;complete=false;reason=e.message;}
    const vars=variables(n,kind),display=p=>[...p].sort((a,b)=>a[0].localeCompare(b[0])).map(([m,c],i)=>{const mon=monomialString(m.split(',').map(Number),vars),v=c<0n?-c:c,body=mon==='1'?String(v):(v===1n?'':v+'*')+mon;return(i?(c<0n?' - ':' + '):c<0n?'-':'')+body;}).join('')||'0';
    return {complete,exact:true,generators:[...generators.values()].map(display),reason,statistics:{operations:ctx.operations,minorsExpanded:ctx.minors,milliseconds:Date.now()-start}};}};
}

export function computeJumpIdeal(data,kind='local',k=1,options={}){
  kind=normalizeKind(kind);k=indexCheck(data,k);
  if(!data.verified)throw Error('普遍複体の検証を通過する flag を使ってください');
  const common={available:true,kind,k,n:data.n,ring:kind==='local'?'Q[t₁±¹,…,tₙ±¹]':'Q[a₁,…,aₙ]',definition:definition(data,kind,k),geometryKey:jumpGeometryKey(data)};
  const forcedLive=kind==='aomoto'&&k===1&&options.liveResonance===true;
  const cached=!options.ignoreCache&&!forcedLive&&JUMP_IDEAL_CACHE.find(c=>c.geometryKey===common.geometryKey&&c.kind===kind&&c.k===k);
  if(cached)return {...common,ideal:{...cached.ideal,generatorCount:cached.ideal.generatorCount??cached.ideal.generators.length},decomposition:cached.decomposition,computation:{...cached.computation,cache:true,sourceId:cached.sourceId}};
  const vars=variables(data.n,kind),special=k>data.n?'empty':k===data.n?'point':null;
  if(special){const generators=special==='empty'?['1']:vars.map(v=>kind==='local'?v+' - 1':v),components=special==='empty'?[]:[{generators,dimension:0,absolutePrime:true,irreducibilityCertificate:'Independent affine linear coordinates (identity / origin).'}];
    return {...common,ideal:{complete:true,exact:true,generators,generatorCount:generators.length,saturated:kind==='local'},decomposition:{complete:true,over:'C',components,radicalGenerators:generators,schemeEqualsRadical:true},computation:{engine:'exact augmentation / dimension boundary',cache:false}};}
  if(kind==='aomoto'&&k===1&&(forcedLive||(!options.ignoreCache&&options.liveResonance!==false))){
    const live=computeLiveResonance(data,options);
    return {...common,
      ideal:{complete:false,exact:true,skipped:true,generators:[],generatorCount:0,reason:'線形部分空間としての resonance を計算しました。jump ideal のスキーム生成元は展開していません。'},
      decomposition:{...live,over:'C',radicalGenerators:null,radicalEqualityVerified:live.complete,irredundancyVerified:live.complete},
      computation:{engine:'Exact live resonance: projective flats and exhaustive real multinet supports',cache:false,live:true,...live.statistics,verification:live.verification}};
  }
  const computed=sparseEngine(data,kind,options).compute(data.n-k+1),full=!!computed.complete&&!computed.generators.length;
  return {...common,ideal:{...computed,generatorCount:computed.generators.length,saturated:kind==='local'?'Laurent generators; polynomial contraction not computed':false},
    decomposition:{complete:full,over:'C',components:full?[{generators:[],dimension:data.n,absolutePrime:true,irreducibilityCertificate:'Zero ideal in a polynomial / Laurent polynomial domain.'}]:[],radicalGenerators:full?[]:null,
      reason:full?null:computed.complete?'定義 ideal は展開済みです。既約成分分解はこの配置では未計算です。':'処理上限のため、表示した式は jump ideal の一部です。全定義 ideal と既約成分分解は未確定です。'},
    computation:{engine:'exact sparse integer expansion of determinantal generators',cache:false,...computed.statistics}};
}
